/**
 * Форматирование Markdown и HTML для сообщений MAX. Функции не экранируют
 * текст автоматически: пользовательские данные нужно передать в escape/escapeHtml.
 */
export declare const bold: (text: string) => string;
export declare const italic: (text: string) => string;
export declare const strikethrough: (text: string) => string;
export declare const code: (text: string) => string;
export declare const pre: (text: string, language?: string) => string;
export declare const link: (text: string, url: string) => string;
/** Экранирует пользовательский текст перед вставкой в Markdown. */
export declare const escape: (text: string) => string;
export declare const boldHtml: (text: string) => string;
export declare const italicHtml: (text: string) => string;
export declare const underlineHtml: (text: string) => string;
export declare const strikethroughHtml: (text: string) => string;
export declare const codeHtml: (text: string) => string;
export declare const preHtml: (text: string, language?: string) => string;
export declare const linkHtml: (text: string, url: string) => string;
/** Экранирует пользовательский текст перед вставкой в HTML. */
export declare const escapeHtml: (text: string) => string;
